mapper.select:
SELECT
    mb_id
FROM pet_cm_reply WHERE cm_reply_id = #{cmReplyId};

SELECT SQL_CALC_FOUND_ROWS pcr.cm_board_id, pcr.cm_reply_id, pcr.mb_id, pcr.contents, DATE_FORMAT(pcr.create_ymd, '%Y-%m-%d %H:%i:%s') AS create_ymd, pcr.create_id, gm.mb_nick, pcb.mb_nick as your_nick, subReplyData.sub_reply_list, gbf.bf_fileurl AS user_profile_url FROM pet_cm_reply pcr INNER JOIN g5_member gm ON pcr.mb_id = gm.mb_id LEFT JOIN g5_board_file gbf ON gbf.bo_table = 'user_profile' AND gm.mb_no = gbf.wr_id LEFT JOIN ( SELECT pcsr.cm_reply_id, JSON_ARRAYAGG( JSON_OBJECT( 'cmSuplyId', pcsr.cm_suply_id, 'mbId', pcsr.mb_id, 'contents', pcsr.contents, 'createYmd', DATE_FORMAT(pcsr.create_ymd, '%Y-%m-%d %H:%i:%s'), 'createId', pcsr.create_id, 'mbNick', gm.mb_nick, 'userProfileUrl', gbf.bf_fileurl ) ) AS sub_reply_list FROM pet_cm_sub_reply pcsr INNER JOIN g5_member gm ON pcsr.mb_id = gm.mb_id LEFT JOIN g5_board_file gbf ON gbf.bo_table = 'user_profile' AND gm.mb_no = gbf.wr_id WHERE pcsr.del_fl = 0 GROUP BY pcsr.cm_reply_id ) subReplyData ON subReplyData.cm_reply_id = pcr.cm_reply_id LEFT JOIN ( SELECT gm.mb_nick, gm.mb_id, pcb.cm_board_id FROM pet_cm_board pcb INNER JOIN g5_member gm ON pcb.mb_id = gm.mb_id ) pcb ON pcr.cm_board_id = pcb.cm_board_id WHERE pcr.del_fl = 0 AND pcb.mb_nick IS NOT NULL
AND pcr.cm_board_id = #{cmBoardId}
AND pcr.mb_id = #{mbId}
ORDER BY pcr.create_ymd LIMIT #{pageNo}, #{pageSize};
